"use server";

import { z } from "zod";
import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { getCartItems, findCart } from "@/lib/cart";
import { priceCart } from "@/lib/pricing";
import { razorpay, razorpayConfigured, verifyPaymentSignature } from "@/lib/razorpay";
import { finalizePayment, markPaymentFailed, newOrderNumber } from "@/lib/orders";
import { rateLimit } from "@/lib/security";
import { track } from "@/lib/analytics";
import { checkoutSchema } from "@/lib/validators";
import { SITE } from "@/lib/site";

async function currentCartLines() {
  const items = await getCartItems();
  return items.filter((i) => i.product.isActive).map((i) => ({ productId: i.productId, quantity: i.quantity, engravingText: i.engravingText }));
}

export async function previewQuote(couponCode: string | null) {
  const quote = await priceCart(await currentCartLines(), couponCode);
  return {
    subtotal: quote.subtotal,
    discount: quote.discount,
    shippingFee: quote.shippingFee,
    taxTotal: quote.taxTotal,
    total: quote.total,
    coupon: quote.coupon?.code ?? null,
    couponError: quote.couponError,
  };
}

export type StartCheckoutResult =
  | {
      ok: true;
      keyId: string;
      razorpayOrderId: string;
      amount: number;
      orderNumber: string;
      preferEmi: boolean;
      prefill: { name: string; email: string; contact: string };
    }
  | { ok: false; error: string };

export async function startCheckout(input: z.input<typeof checkoutSchema> & { saveAddress?: boolean }): Promise<StartCheckoutResult> {
  const user = await getCurrentUser();
  if (!user) return { ok: false, error: "Please sign in to place your order." };
  if (!(await rateLimit("checkout", 15, 10 * 60))) return { ok: false, error: "Too many attempts. Please wait a few minutes." };
  if (!razorpayConfigured()) return { ok: false, error: "Online payments are being set up. Please call or WhatsApp us to order." };

  const parsed = checkoutSchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: parsed.error.issues[0]?.message ?? "Please check your details." };
  const { address, email, couponCode, preferEmi, notes } = parsed.data;

  const quote = await priceCart(await currentCartLines(), couponCode);
  if (quote.lines.length === 0) return { ok: false, error: "Your cart is empty." };
  const short = quote.lines.find((l) => l.quantity > l.stock);
  if (short) return { ok: false, error: `Only ${short.stock} left of "${short.name}". Please update your cart.` };
  if (couponCode && quote.couponError) return { ok: false, error: quote.couponError };

  const order = await db.order.create({
    data: {
      orderNumber: newOrderNumber(),
      userId: user.id,
      email,
      phone: address.phone,
      shippingAddress: address,
      subtotal: quote.subtotal,
      discount: quote.discount,
      shippingFee: quote.shippingFee,
      taxTotal: quote.taxTotal,
      total: quote.total,
      couponId: quote.coupon?.id,
      preferEmi,
      notes: notes || null,
      items: {
        create: quote.lines.map((l) => ({
          productId: l.productId, name: l.name, sku: l.sku, image: l.image, unitPrice: l.unitPrice,
          quantity: l.quantity, gstRate: l.gstRate, engravingText: l.engravingText,
        })),
      },
      events: { create: { status: "CREATED", note: "Checkout started" } },
    },
  });

  let rzpOrder;
  try {
    rzpOrder = await razorpay().orders.create({
      amount: order.total,
      currency: "INR",
      receipt: order.orderNumber,
      notes: { orderId: order.id, orderNumber: order.orderNumber, store: SITE.name },
    });
  } catch (err) {
    console.error("Razorpay order creation failed", err);
    await db.order.update({ where: { id: order.id }, data: { status: "CANCELLED", events: { create: { status: "GATEWAY_ERROR", note: "Could not create Razorpay order" } } } });
    return { ok: false, error: "Payment gateway is unavailable right now. Please try again." };
  }
  await db.order.update({ where: { id: order.id }, data: { razorpayOrderId: rzpOrder.id } });

  if (input.saveAddress) {
    const count = await db.address.count({ where: { userId: user.id } });
    const dup = await db.address.findFirst({ where: { userId: user.id, line1: address.line1, pincode: address.pincode } });
    if (!dup && count < 10) await db.address.create({ data: { ...address, userId: user.id, isDefault: count === 0 } });
  }
  await track("CHECKOUT_START", { value: order.total });

  return {
    ok: true,
    keyId: process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || process.env.RAZORPAY_KEY_ID!,
    razorpayOrderId: rzpOrder.id,
    amount: order.total,
    orderNumber: order.orderNumber,
    preferEmi,
    prefill: { name: address.name, email, contact: address.phone },
  };
}

const verifySchema = z.object({
  razorpay_order_id: z.string().regex(/^order_[A-Za-z0-9]+$/),
  razorpay_payment_id: z.string().regex(/^pay_[A-Za-z0-9]+$/),
  razorpay_signature: z.string().regex(/^[a-f0-9]{64}$/),
});

export async function verifyPayment(input: z.input<typeof verifySchema>): Promise<{ ok: true; orderNumber: string } | { ok: false; error: string }> {
  const user = await getCurrentUser();
  if (!user) return { ok: false, error: "Session expired. Your payment is safe — check My Orders after signing in." };
  const parsed = verifySchema.safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid payment response." };
  const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = parsed.data;

  const order = await db.order.findUnique({ where: { razorpayOrderId: razorpay_order_id }, select: { userId: true } });
  if (!order || order.userId !== user.id) return { ok: false, error: "Order not found." };
  if (!verifyPaymentSignature(razorpay_order_id, razorpay_payment_id, razorpay_signature)) {
    return { ok: false, error: "Payment signature verification failed." };
  }

  let result: Awaited<ReturnType<typeof finalizePayment>>;
  try {
    result = await finalizePayment(razorpay_order_id, razorpay_payment_id);
  } catch (err) {
    console.error("finalizePayment failed", err);
    result = { ok: false, reason: "gateway unreachable" };
  }
  if (!result.ok) return { ok: false, error: `We could not confirm your payment (${result.reason}). If money was deducted it will be reconciled automatically.` };

  const cart = await findCart();
  if (cart) await db.cartItem.deleteMany({ where: { cartId: cart.id } });
  return { ok: true, orderNumber: result.orderNumber };
}

export async function reportPaymentFailure(razorpayOrderId: string, description: string) {
  const user = await getCurrentUser();
  if (!user || !/^order_[A-Za-z0-9]+$/.test(razorpayOrderId)) return;
  const order = await db.order.findUnique({ where: { razorpayOrderId }, select: { userId: true } });
  if (order?.userId !== user.id) return;
  await markPaymentFailed(razorpayOrderId, `Checkout: ${String(description).slice(0, 300)}`);
}
